"use client";

/* ─────────────────────────────────────────────────────────
 * MAGNIFYING DOCK: a dock that opens its tools in place
 *
 *   lens     tools near the pointer grow and the row parts around
 *            them; the tray widens with them. Transforms only,
 *            eased in one frame loop that sleeps when it settles
 *   label    one name rides above the tool under the pointer,
 *            gliding from tool to tool while its letters morph
 *   select   a soft pad glides to the chosen tool and keeps
 *            riding its magnification
 *   open     a tool with content grows the dock itself up into
 *            its panel: the tray widens and rises, the title
 *            morphs, and switching tools slides the new panel in
 *            from the side you moved toward
 *   close    choose the open tool again, press Escape or click
 *            away, and the panel folds back into the tray
 *
 * Every tool is a real button in a toolbar: arrow keys move
 * between them, and keyboard focus magnifies like the pointer.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { useDockLens } from "./use-dock-lens";

export interface DockItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  /** What the dock opens into when this tool is chosen. Without it, the tool only selects. */
  content?: React.ReactNode;
  /** The open panel's heading; defaults to label. */
  title?: string;
  /** A count on the icon, e.g. unread messages; 0 folds it away. */
  badge?: number;
  disabled?: boolean;
}

export interface MagnifyingDockProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  items: DockItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  label?: string;
  /** Rest size of a tool in px, 32–56. */
  size?: number;
  /** Peak scale under the pointer, 1–2. */
  magnification?: number;
  /** Width of the open panel in px; it never exceeds the space available. */
  panelWidth?: number;
}

const GAP = 6;
const INSET = 8;
const LABEL_ROOM = 34;
const clamp = (n: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, Number.isFinite(n) ? n : lo));

function Pane({
  dir,
  reduced,
  leaving,
  onDone,
  children,
}: {
  dir: number;
  reduced: boolean;
  leaving?: boolean;
  onDone?: () => void;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced || !dir) {
      if (leaving) onDone?.();
      return;
    }
    const frames = leaving
      ? [
          { opacity: 1, transform: "none", filter: "blur(0px)" },
          {
            opacity: 0,
            transform: `translateX(${-dir * 24}px)`,
            filter: "blur(4px)",
          },
        ]
      : [
          {
            opacity: 0,
            transform: `translateX(${dir * 24}px)`,
            filter: "blur(4px)",
          },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ];
    const animation = el.animate(frames, {
      duration: leaving ? 220 : 360,
      delay: leaving ? 0 : 40,
      easing: EASE_OUT,
      fill: leaving ? "forwards" : "backwards",
    });
    if (leaving) animation.onfinish = () => onDone?.();
    return () => animation.cancel();
    // Runs once per pane: each pane is keyed by its tool.
  }, []);
  return (
    <div
      ref={ref}
      inert={leaving}
      aria-hidden={leaving || undefined}
      className={
        leaving ? "pointer-events-none absolute inset-x-0 top-0" : "relative"
      }
    >
      {children}
    </div>
  );
}

export function MagnifyingDock({
  items,
  value,
  defaultValue,
  onValueChange,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  label = "Tools",
  size = 40,
  magnification = 1.6,
  panelWidth = 340,
  className = "",
  ...props
}: MagnifyingDockProps) {
  const reduced = useInteractionReducedMotion();
  const S = clamp(size, 32, 56);
  const M = clamp(magnification, 1, 2);
  const id = React.useId();

  const [ownValue, setOwnValue] = React.useState(
    defaultValue ?? items.find((item) => !item.disabled)?.id,
  );
  const selectedId = value ?? ownValue;
  const selected = Math.max(
    0,
    items.findIndex((item) => item.id === selectedId),
  );
  const [ownOpen, setOwnOpen] = React.useState(defaultOpen);
  const open = (openProp ?? ownOpen) && Boolean(items[selected]?.content);

  const [hovered, setHovered] = React.useState<number | null>(null);
  const lens = useDockLens({
    count: items.length,
    size: S,
    gap: GAP,
    inset: INSET,
    magnification: M,
    reduced,
    onHover: setHovered,
  });

  const root = React.useRef<HTMLDivElement>(null);
  const content = React.useRef<HTMLDivElement>(null);
  const [rootWidth, setRootWidth] = React.useState(0);
  const panelW = Math.max(
    200,
    Math.min(panelWidth, rootWidth ? rootWidth - 16 : panelWidth),
  );

  // The panel shows the open tool; while folding away it keeps the last one.
  const [shown, setShown] = React.useState(selected);
  const [leaving, setLeaving] = React.useState<
    { key: number; index: number; dir: number }[]
  >([]);
  const [slideDir, setSlideDir] = React.useState(0);
  const [wasOpen, setWasOpen] = React.useState(open);
  if (open !== wasOpen) setWasOpen(open);
  if (open && shown !== selected) {
    // Switching inside an open panel slides; opening on a different tool just shows it.
    const nextDir = wasOpen ? Math.sign(selected - shown) : 0;
    setSlideDir(nextDir);
    if (wasOpen && !reduced) {
      setLeaving((l) => [
        ...l,
        {
          key: (l.length ? l[l.length - 1].key : 0) + 1,
          index: shown,
          dir: nextDir,
        },
      ]);
    }
    setShown(selected);
  }

  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };
  const choose = (index: number) => {
    const item = items[index];
    if (!item || item.disabled) return;
    if (item.id !== selectedId) {
      if (value === undefined) setOwnValue(item.id);
      onValueChange?.(item.id);
    }
    if (!item.content) {
      if (open) setOpen(false);
      return;
    }
    if (!open) setSlideDir(0);
    setOpen(!(open && item.id === selectedId));
  };

  React.useLayoutEffect(() => {
    lens.set({ selected, open, panelWidth: panelW });
  });

  // Sizes the open panel from its content, and the panel width from the space the dock has.
  React.useLayoutEffect(() => {
    const el = content.current;
    const box = root.current;
    if (!el || !box) return;
    const measure = () => {
      lens.set({ panelHeight: el.offsetHeight });
      setRootWidth((w) => (w === box.clientWidth ? w : box.clientWidth));
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    observer.observe(box);
    return () => observer.disconnect();
  }, []);

  // Click away to fold the panel.
  React.useEffect(() => {
    if (!open) return;
    const away = (event: PointerEvent) => {
      if (!root.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", away);
    return () => document.removeEventListener("pointerdown", away);
  }, [open]);

  const enabled = items
    .map((item, index) => ({ item, index }))
    .filter(({ item }) => !item.disabled);
  const onToolKey = (event: React.KeyboardEvent, index: number) => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    const at = enabled.findIndex((entry) => entry.index === index);
    const next =
      event.key === "Home"
        ? enabled[0]
        : event.key === "End"
          ? enabled.at(-1)
          : enabled[
              (at + (event.key === "ArrowRight" ? 1 : -1) + enabled.length) %
                enabled.length
            ];
    if (next) lens.focusIcon(next.index);
  };

  const band = S + 2 * INSET;
  const headroom = Math.ceil(S * (M - 1)) + LABEL_ROOM;
  const restWidth =
    items.length * S + Math.max(0, items.length - 1) * GAP + 2 * INSET;
  const shownItem = items[shown] ?? items[selected];
  const hoverItem = hovered !== null ? items[hovered] : undefined;

  return (
    <div
      ref={root}
      {...props}
      onKeyDown={(event) => {
        props.onKeyDown?.(event);
        if (event.key === "Escape" && open) {
          event.preventDefault();
          setOpen(false);
          lens.focusIcon(selected);
        }
      }}
      className={`relative w-full text-foreground ${className}`}
      style={{ height: band + headroom, ...props.style }}
    >
      {/* The tray: one surface that widens with the lens and rises into the panel. */}
      <div
        ref={(el) => {
          lens.attachSurface(el);
        }}
        aria-hidden="true"
        className="absolute bottom-0 left-1/2 -translate-x-1/2 border border-border bg-background"
        style={{ width: restWidth, height: band, borderRadius: band / 2 }}
      />

      <div
        ref={(el) => {
          lens.attachRow(el);
        }}
        role="toolbar"
        aria-label={label}
        onPointerMove={(e) => lens.pointer(e)}
        onPointerLeave={() => lens.leave()}
        className="absolute bottom-0 left-1/2 z-10 flex -translate-x-1/2 items-end"
        style={{
          padding: INSET,
          paddingTop: INSET + (open ? 0 : Math.ceil(S * (M - 1))),
          gap: GAP,
        }}
      >
        <div
          ref={(el) => {
            lens.attachPad(el);
          }}
          aria-hidden="true"
          className="absolute left-0 origin-bottom rounded-[12px] bg-muted"
          style={{ bottom: INSET, width: S, height: S }}
        />

        {items.map((item, index) => {
          const isSelected = index === selected;
          const badge = Math.max(0, Math.round(item.badge ?? 0));
          return (
            <div
              key={item.id}
              className="relative shrink-0"
              style={{ width: S, height: S }}
            >
              <button
                ref={(el) => {
                  lens.attachIcon(index, el);
                }}
                type="button"
                aria-label={item.label}
                {...(item.content
                  ? {
                      "aria-expanded": open && isSelected,
                      "aria-controls": `${id}-panel`,
                    }
                  : { "aria-pressed": isSelected })}
                disabled={item.disabled}
                tabIndex={isSelected ? 0 : -1}
                onClick={() => choose(index)}
                onFocus={() => lens.set({ focus: index })}
                onBlur={() => lens.set({ focus: null })}
                onKeyDown={(event) => onToolKey(event, index)}
                className={`cursor-pointer disabled:cursor-default absolute inset-0 flex origin-bottom items-center justify-center rounded-[12px] transition-colors duration-200 disabled:opacity-35 ${
                  isSelected
                    ? "text-foreground"
                    : "text-muted-foreground hover:text-foreground"
                } ${INTERACTION_FOCUS}`}
              >
                <span
                  aria-hidden="true"
                  className="flex size-[50%] items-center justify-center [&>svg]:size-full [&>svg]:stroke-[1.75]"
                >
                  {item.icon}
                </span>
                {item.badge !== undefined && (
                  <span
                    aria-hidden="true"
                    className="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[9.5px] font-medium tabular-nums text-primary-foreground"
                    style={{
                      opacity: badge ? 1 : 0,
                      transform: badge ? "none" : "scale(0.4)",
                      transition: reduced
                        ? "none"
                        : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}`,
                    }}
                  >
                    <NumberRoll value={badge} duration={700} />
                  </span>
                )}
              </button>
            </div>
          );
        })}

        {/* One label, gliding between tools; its words morph as it moves. */}
        <div
          ref={(el) => {
            lens.attachLabel(el);
          }}
          aria-hidden="true"
          className="pointer-events-none absolute left-0 whitespace-nowrap rounded-full border border-border bg-background px-2.5 py-1 text-[11.5px] font-medium text-foreground"
          style={{ bottom: band + 6, opacity: 0 }}
        >
          <TextMorph>{hoverItem?.label ?? ""}</TextMorph>
        </div>
      </div>

      <div
        ref={(el) => {
          lens.attachPanel(el);
        }}
        id={`${id}-panel`}
        role="region"
        aria-label={shownItem?.title ?? shownItem?.label}
        inert={!open}
        className="absolute left-1/2 -translate-x-1/2 overflow-hidden"
        style={{
          bottom: band - 1,
          width: panelW,
          height: 0,
          opacity: 0,
          visibility: "hidden",
        }}
      >
        <div
          ref={content}
          className="absolute bottom-0 left-1/2 -translate-x-1/2 px-4 pb-3.5 pt-4"
          style={{ width: panelW }}
        >
          <p className="text-[13px] font-medium text-foreground">
            <TextMorph>{shownItem?.title ?? shownItem?.label ?? ""}</TextMorph>
          </p>
          <div className="relative mt-3">
            {leaving.map((l) => (
              <Pane
                key={`out-${l.key}`}
                dir={l.dir}
                reduced={reduced}
                leaving
                onDone={() =>
                  setLeaving((all) => all.filter((x) => x.key !== l.key))
                }
              >
                {items[l.index]?.content}
              </Pane>
            ))}
            <Pane key={shownItem?.id} dir={slideDir} reduced={reduced}>
              {shownItem?.content}
            </Pane>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/*
 * The dock's motion engine. One frame loop eases every moving part toward its target and
 * stops when they all settle, so a resting dock costs nothing.
 *
 *   lens     tools near the pointer scale up and the row parts around them. Distances are
 *            measured from fixed rest positions, so growth never feeds back into the pointer
 *            maths. Only transforms move: no layout while you sweep across it.
 *   marker   the selected tool's pad glides to the new tool and rides its magnification.
 *   label    one name that follows the tool under the pointer and lifts above its new height.
 *   surface  the tray widens with the lens, and grows up into the open panel.
 */

export type DockLensOptions = {
  count: number;
  size: number;
  gap: number;
  inset: number;
  magnification: number;
  reduced: boolean;
  onHover: (index: number | null) => void;
};

type Targets = {
  pointer: number | null;
  focus: number | null;
  selected: number;
  open: boolean;
  panelHeight: number;
  panelWidth: number;
};

// Seconds to close ~63% of the gap. While the pointer sweeps the lens is all but attached to it (TRACK); entering and
// leaving the dock, where the targets jump, ease more gently (LENS) so the tools swell and settle instead of snapping.

export function useDockLens({
  count,
  size,
  gap,
  inset,
  magnification,
  reduced,
  onHover,
}: DockLensOptions) {
  const icons = React.useRef<(HTMLElement | null)[]>([]);
  const pad = React.useRef<HTMLDivElement>(null);
  const label = React.useRef<HTMLDivElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const panel = React.useRef<HTMLDivElement>(null);
  const row = React.useRef<HTMLDivElement>(null);

  const target = React.useRef<Targets>({
    pointer: null,
    focus: null,
    selected: 0,
    open: false,
    panelHeight: 0,
    panelWidth: 0,
  });
  const sim = React.useRef({
    s: [] as number[],
    sV: [] as number[],
    o: [] as number[],
    pad: NaN,
    padV: 0,
    labelX: NaN,
    labelLift: 0,
    labelOpacity: 0,
    open: 0,
    openV: 0,
    height: 0,
    heightV: 0,
    width: 0,
    widthV: 0,
    last: 0,
  });
  const frame = React.useRef(0);
  const hovered = React.useRef<number | null>(null);
  const origin = React.useRef<number | null>(null);
  const opts = React.useRef({
    count,
    size,
    gap,
    inset,
    magnification,
    reduced,
    onHover,
  });
  React.useLayoutEffect(() => {
    opts.current = { count, size, gap, inset, magnification, reduced, onHover };
  });

  const tick = React.useCallback(function runTick(now: number) {
    frame.current = 0;
    const {
      count: n,
      size: S,
      gap: G,
      inset: P,
      magnification: M,
      reduced: still,
      onHover: hover,
    } = opts.current;
    const t = target.current;
    const st = sim.current;
    const dt = st.last ? Math.min(0.064, (now - st.last) / 1000) : 1 / 60;
    st.last = now;
    const ease = (tau: number) => (still ? 1 : 1 - Math.exp(-dt / tau));
    let moving = false;
    const approach = (from: number, to: number, k: number) => {
      const next = Number.isNaN(from) ? to : from + (to - from) * k;
      if (Math.abs(next - to) > 0.0005) moving = true;
      return Math.abs(next - to) <= 0.0005 ? to : next;
    };

    const step = S + G;
    const rest = (i: number) => P + i * step + S / 2;
    const anchor = t.focus !== null ? rest(t.focus) : t.pointer;
    const reach = S * 2.4;
    const peak = still ? 1 : t.open ? Math.min(M, 1.22) : M;

    // The lens: scale per tool with organic settling when the pointer leaves
    let extra = 0;
    for (let i = 0; i < n; i++) {
      const d = anchor === null ? Infinity : Math.abs(anchor - rest(i));
      const f = d < reach ? (1 + Math.cos((d / reach) * Math.PI)) / 2 : 0;
      const goal = 1 + (peak - 1) * f;

      if (anchor === null && !still) {
        // Soft harmonic breath as icons return to rest (visualDuration ~0.28s)
        const sCur = st.s[i] ?? 1;
        const kIcon = 260,
          cIcon = 24;
        st.sV[i] =
          (st.sV[i] ?? 0) +
          (-kIcon * (sCur - 1) - cIcon * (st.sV[i] ?? 0)) * dt;
        st.s[i] = sCur + st.sV[i] * dt;
        if (Math.abs(st.s[i] - 1) < 0.002 && Math.abs(st.sV[i]) < 0.02) {
          st.s[i] = 1;
          st.sV[i] = 0;
        } else {
          moving = true;
        }
      } else {
        st.sV[i] = 0;
        st.s[i] = approach(
          st.s[i] ?? 1,
          goal,
          ease(Math.abs(goal - (st.s[i] ?? 1)) > 0.08 ? 0.028 : 0.016),
        );
      }
      extra += S * (st.s[i] - 1);
    }
    let run = 0;
    for (let i = 0; i < n; i++) {
      const e = S * (st.s[i] - 1);
      st.o[i] = run + e / 2 - extra / 2;
      run += e;
      const el = icons.current[i];
      if (el)
        el.style.transform = `translate3d(${st.o[i]}px,0,0) scale(${st.s[i]})`;
    }

    // The pad snaps with a lively harmonic spring (hint of overshoot for magnetic tactile feel)
    const padGoal = rest(t.selected);
    if (still || Number.isNaN(st.pad)) {
      st.pad = padGoal;
      st.padV = 0;
    } else {
      const kPad = 360,
        cPad = 28;
      st.padV =
        (st.padV ?? 0) +
        (-kPad * (st.pad - padGoal) - cPad * (st.padV ?? 0)) * dt;
      st.pad += st.padV * dt;
      if (Math.abs(st.pad - padGoal) < 0.25 && Math.abs(st.padV) < 4) {
        st.pad = padGoal;
        st.padV = 0;
      } else {
        moving = true;
      }
    }
    const u = Math.max(0, Math.min(n - 1, (st.pad - rest(0)) / step));
    const i0 = Math.floor(u),
      i1 = Math.min(n - 1, i0 + 1),
      w = u - i0;
    const padOffset = (st.o[i0] ?? 0) * (1 - w) + (st.o[i1] ?? 0) * w;
    const padScale = (st.s[i0] ?? 1) * (1 - w) + (st.s[i1] ?? 1) * w;
    if (pad.current)
      pad.current.style.transform = `translate3d(${st.pad - S / 2 + padOffset}px,0,0) scale(${padScale})`;

    // The label: glides crisply with the tool and lifts above its height
    const near =
      anchor === null
        ? null
        : Math.max(0, Math.min(n - 1, Math.round((anchor - rest(0)) / step)));
    if (near !== hovered.current && near !== null) hover(near);
    if (near !== null) hovered.current = near;
    const shown = near ?? hovered.current;
    if (shown !== null) {
      st.labelX = approach(
        st.labelX,
        rest(shown) + (st.o[shown] ?? 0),
        ease(0.038),
      );
      st.labelLift = approach(
        st.labelLift,
        S * ((st.s[shown] ?? 1) - 1),
        ease(0.018),
      );
    }
    st.labelOpacity = approach(
      st.labelOpacity,
      near !== null && !t.open ? 1 : 0,
      ease(near !== null ? 0.04 : 0.035),
    );
    if (label.current) {
      label.current.style.transform = `translate3d(${st.labelX}px,${-st.labelLift - (1 - st.labelOpacity) * 4}px,0) translateX(-50%)`;
      label.current.style.opacity = String(st.labelOpacity);
    }

    // The surface: a tray that widens with the lens and grows up into the panel via smooth critically-damped spring
    const restWidth = n * S + (n - 1) * G + 2 * P;
    const hGoal = t.open ? t.panelHeight : 0;
    const wGoal = t.open ? Math.max(restWidth, t.panelWidth) : restWidth;
    const oGoal = t.open ? 1 : 0;

    if (still) {
      st.open = oGoal;
      st.height = hGoal;
      st.width = wGoal;
      st.openV = 0;
      st.heightV = 0;
      st.widthV = 0;
    } else {
      const kSurf = 240,
        cSurf = 31;
      st.heightV =
        (st.heightV ?? 0) +
        (-kSurf * (st.height - hGoal) - cSurf * (st.heightV ?? 0)) * dt;
      st.height += st.heightV * dt;
      if (Math.abs(st.height - hGoal) < 0.3 && Math.abs(st.heightV) < 4) {
        st.height = hGoal;
        st.heightV = 0;
      } else {
        moving = true;
      }

      st.widthV =
        (st.widthV ?? 0) +
        (-kSurf * (st.width - wGoal) - cSurf * (st.widthV ?? 0)) * dt;
      st.width += st.widthV * dt;
      if (Math.abs(st.width - wGoal) < 0.3 && Math.abs(st.widthV) < 4) {
        st.width = wGoal;
        st.widthV = 0;
      } else {
        moving = true;
      }

      st.openV =
        (st.openV ?? 0) +
        (-kSurf * (st.open - oGoal) - cSurf * (st.openV ?? 0)) * dt;
      st.open += st.openV * dt;
      if (Math.abs(st.open - oGoal) < 0.002 && Math.abs(st.openV) < 0.05) {
        st.open = oGoal;
        st.openV = 0;
      } else {
        moving = true;
      }
    }

    const band = S + 2 * P;
    const wide = Math.max(st.width, restWidth + extra);
    if (surface.current) {
      surface.current.style.width = `${wide}px`;
      surface.current.style.height = `${band + st.height}px`;
      surface.current.style.borderRadius = `${band / 2 + (20 - band / 2) * Math.min(1, st.open * 1.6)}px`;
    }
    if (panel.current) {
      panel.current.style.height = `${st.height}px`;
      panel.current.style.width = `${wide - 2}px`;
      panel.current.style.opacity = String(
        Math.max(0, (st.open - 0.35) / 0.65),
      );
      panel.current.style.visibility =
        st.open < 0.01 && !t.open ? "hidden" : "visible";
    }

    if (moving) frame.current = requestAnimationFrame(runTick);
    else st.last = 0;
  }, []);

  const kick = React.useCallback(() => {
    if (!frame.current) frame.current = requestAnimationFrame(tick);
  }, [tick]);

  // A rAF id kept in a ref must be cleared on unmount, or StrictMode's remount thinks the loop is still running.
  React.useEffect(() => {
    // A scroll under a resting pointer moves the row: measure again on the next move.
    const forget = () => {
      origin.current = null;
    };
    window.addEventListener("scroll", forget, { passive: true, capture: true });
    window.addEventListener("resize", forget);
    return () => {
      window.removeEventListener("scroll", forget, { capture: true });
      window.removeEventListener("resize", forget);
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    };
  }, []);
  React.useLayoutEffect(() => {
    sim.current.last = 0;
    tick(performance.now());
  }, [count, size, gap, inset, magnification, reduced, tick]);

  const attachRow = React.useCallback((el: HTMLDivElement | null) => {
    row.current = el;
  }, []);
  const attachPad = React.useCallback((el: HTMLDivElement | null) => {
    pad.current = el;
  }, []);
  const attachLabel = React.useCallback((el: HTMLDivElement | null) => {
    label.current = el;
  }, []);
  const attachSurface = React.useCallback((el: HTMLDivElement | null) => {
    surface.current = el;
  }, []);
  const attachPanel = React.useCallback((el: HTMLDivElement | null) => {
    panel.current = el;
  }, []);
  const attachIcon = React.useCallback(
    (index: number, el: HTMLElement | null) => {
      icons.current[index] = el;
    },
    [],
  );
  const focusIcon = React.useCallback((index: number) => {
    icons.current[index]?.focus({ preventScroll: true });
  }, []);

  const set = React.useCallback(
    (next: Partial<Targets>) => {
      Object.assign(target.current, next);
      kick();
    },
    [kick],
  );

  const pointer = React.useCallback(
    (event: React.PointerEvent) => {
      if (event.pointerType === "touch" || !row.current) return;
      // The row never moves under the lens (only transforms do), so its edge is read once per hover.
      if (origin.current === null)
        origin.current = row.current.getBoundingClientRect().left;
      target.current.focus = null;
      target.current.pointer = event.clientX - origin.current;
      kick();
    },
    [kick],
  );

  const leave = React.useCallback(() => {
    origin.current = null;
    target.current.pointer = null;
    kick();
  }, [kick]);

  return React.useMemo(
    () => ({
      attachIcon,
      attachPad,
      attachLabel,
      attachSurface,
      attachPanel,
      attachRow,
      focusIcon,
      set,
      pointer,
      leave,
    }),
    [
      attachIcon,
      attachPad,
      attachLabel,
      attachSurface,
      attachPanel,
      attachRow,
      focusIcon,
      set,
      pointer,
      leave,
    ],
  );
}

